#!/usr/bin/env bash
# GENERATED by tools/landed_parent/lp.py: lockstep bench dsdv_idx_rg3_bf (flat) vs dsdv_idx_rg3_bf_lp + mutants [1, 2, 4] + region audit.
# Run on the FLEET (ot-run), never on localhost.  Exit 0 iff MUT 0 PASSES, every mutant FAILS and the audit PASSES.
#   bash rtl/dsrom_sys/s81_dv/idx/lp/dsdv_idx_rg3_bf_lp_bench.sh OUTDIR        (SIM=iverilog default | verilator; VERILATOR, VL_JOBS, VL_EXTRA,
#   MUTS="0 1 .." optional overrides)
set -u
cd "${LP_ROOT:-$(git -C "$(dirname "$0")" rev-parse --show-toplevel 2>/dev/null || (cd "$(dirname "$0")/../../../../.." && pwd))}"
OUT=${1:-lp_bench_out}; mkdir -p "$OUT"; SIM=${SIM:-iverilog}; rc=0
SRCS="rtl/dsrom_sys/s81_dv/idx/dsdv_idx_rg3_bf.sv rtl/hdc/ot_hdc_fastfp.sv rtl/hdc/ot_hdc_delay.sv rtl/hdc/v41x/ot_hdc_v41x_idx_arith.sv rtl/hdc/v41x/ot_hdc_v41x_idx.sv rtl/lib/ot_rst_relay.sv rtl/hdc/ot_hdc_prefix.sv rtl/hdc/ot_hdc_fp32_add_lat.sv rtl/hdc/ot_hdc_fp32_add_lat_nr.sv rtl/hdc/v41x/ot_hdc_v41x_idx_arith_lat.sv rtl/hdc/v41x/ot_hdc_v41x_idx_lat.sv rtl/hdc/v41x/ot_hdc_v41x_idx_hslice.sv rtl/hdc/v41x/ot_hdc_v41x_idx_chunk_el.sv physical/asap7_memory_macros/ot_sram_1r1w_1024x256_m2_r2c2/ot_sram_1r1w_1024x256_m2_r2c2.v rtl/dsrom_sys/s81_dv/idx/dsdv_idx_rg2.sv rtl/dsrom_sys/s81_dv/idx/dsdv_idx_rg3_br.sv rtl/dsrom_sys/s81_dv/idx/dsdv_idx_rg3_band.sv rtl/common/landed_parent/ot_pl_land.sv rtl/common/landed_parent/ot_pl_land_rst_copy.sv rtl/common/landed_parent/ot_pl_land_split.sv rtl/dsrom_sys/s81_dv/idx/lp/dsdv_idx_rg3_bf_lp.sv rtl/dsrom_sys/s81_dv/idx/lp/tb_dsdv_idx_rg3_bf_lp.sv"
python3 tools/landed_parent/lp.py audit tools/landed_parent/specs/s81_idx_rg3_band.json > "$OUT/audit.log" 2>&1 && echo "AUDIT PASS" || { echo "AUDIT FAIL"; rc=1; }
python3 tools/landed_parent/lp.py audit tools/landed_parent/specs/s81_idx_rg3_band.json --rtl "$OUT/unland.sv" --make-unland > "$OUT/audit_unland.log" 2>&1 \
  && { echo "AUDIT-UNLAND PASSED (should FAIL)"; rc=1; } || echo "AUDIT-UNLAND FAIL (expected)"
for m in ${MUTS:-0 1 2 4}; do
  if [ "$SIM" = verilator ]; then
    ${VERILATOR:-verilator} --binary -j ${VL_JOBS:-8} -I. -Wno-fatal -Wno-lint -Wno-style -Wno-TIMESCALEMOD -Wno-WIDTHCONCAT -O1 ${VL_EXTRA:-} --top-module tb_dsdv_idx_rg3_bf_lp -GMUT=$m  $SRCS -Mdir "$OUT/obj$m" > "$OUT/build_$m.log" 2>&1 \
      && "$OUT/obj$m/Vtb_dsdv_idx_rg3_bf_lp" > "$OUT/mut$m.log" 2>&1
  else
    iverilog -g2012 -I. -o "$OUT/sim$m" -s tb_dsdv_idx_rg3_bf_lp -Ptb_dsdv_idx_rg3_bf_lp.MUT=$m  $SRCS > "$OUT/build_$m.log" 2>&1 \
      && vvp -n "$OUT/sim$m" > "$OUT/mut$m.log" 2>&1
  fi
  r=$(grep -o 'LP_LOCKSTEP [A-Z]*' "$OUT/mut$m.log" 2>/dev/null | head -1)
  echo "MUT $m: ${r:-NO_RESULT (see $OUT/build_$m.log)}"
  if [ $m -eq 0 ]; then [ "$r" = "LP_LOCKSTEP PASS" ] || rc=1; else [ "$r" = "LP_LOCKSTEP FAIL" ] || rc=1; fi
done
echo "BENCH_EXIT $rc"; exit $rc
